"use strict";(self.webpackChunkcoursesmith_site=self.webpackChunkcoursesmith_site||[]).push([["2901"],{2089(e,n,t){t.r(n),t.d(n,{metadata:()=>i,default:()=>u,frontMatter:()=>r,contentTitle:()=>c,toc:()=>l,assets:()=>d});var i=JSON.parse('{"id":"m24-cloud-governance-audit/lesson","title":"Lesson: Cloud Governance and Compliance Automation","description":"Every AWS module so far in this course either shows you what exists (Module 21\'s inventory,","source":"@site/docs/m24-cloud-governance-audit/lesson.md","sourceDirName":"m24-cloud-governance-audit","slug":"/m24-cloud-governance-audit/lesson","permalink":"/307-aipython-site/docs/m24-cloud-governance-audit/lesson","draft":false,"unlisted":false,"tags":[],"version":"current","sidebarPosition":1,"frontMatter":{"sidebar_position":1,"title":"Lesson: Cloud Governance and Compliance Automation"},"sidebar":"courseSidebar","previous":{"title":"Deep Dive (Part 2)","permalink":"/307-aipython-site/docs/m23-multi-region-inventory/deep-dive"},"next":{"title":"Lab: Cloud Governance and Compliance Automation","permalink":"/307-aipython-site/docs/m24-cloud-governance-audit/lab"}}'),o=t(4848),s=t(8453),a=t(7684);let r={sidebar_position:1,title:"Lesson: Cloud Governance and Compliance Automation"},c="Cloud Governance and Compliance Automation",d={},l=[{value:"1. The inspector&#39;s checklist, not the repair crew",id:"1-the-inspectors-checklist-not-the-repair-crew",level:2},{value:"2. Policy as data \u2014 rules you can read without reading Python",id:"2-policy-as-data--rules-you-can-read-without-reading-python",level:2},{value:"3. Evidence composes with the inventory, it does not duplicate it",id:"3-evidence-composes-with-the-inventory-it-does-not-duplicate-it",level:2},{value:"4. Detection is pure \u2014 provably, not just by convention",id:"4-detection-is-pure--provably-not-just-by-convention",level:2},{value:"5. A finding carries evidence, not a bare verdict",id:"5-a-finding-carries-evidence-not-a-bare-verdict",level:2},{value:"6. Exceptions suppress, they never delete",id:"6-exceptions-suppress-they-never-delete",level:2},{value:"Common pitfalls",id:"common-pitfalls",level:2}];function h(e){let n={admonition:"admonition",code:"code",h1:"h1",h2:"h2",header:"header",li:"li",mermaid:"mermaid",p:"p",pre:"pre",strong:"strong",ul:"ul",...(0,s.R)(),...e.components};return(0,o.jsxs)(o.Fragment,{children:[(0,o.jsx)(a.A,{src:"decks/m24-concepts.html",title:"M24 \u2014 Cloud Governance and Compliance Automation"}),"\n",(0,o.jsx)(n.header,{children:(0,o.jsx)(n.h1,{id:"cloud-governance-and-compliance-automation",children:"Cloud Governance and Compliance Automation"})}),"\n",(0,o.jsxs)(n.p,{children:["Every AWS module so far in this course either shows you what exists (Module 21's inventory,\nModule 23's multi-region scan) or does something to a resource (Module 22's report upload, queue\nsend). This module does neither. It checks what already exists against a set of rules written down\nin a file, and produces a list of exactly what breaks those rules \u2014 nothing more. It is the\n",(0,o.jsx)(n.code,{children:"platformops"})," project's first ",(0,o.jsx)(n.strong,{children:"audit"})," tool, and audits have one job: find and report, never fix."]}),"\n",(0,o.jsx)(n.admonition,{title:"Why this matters at work",type:"info",children:(0,o.jsx)(n.p,{children:"A cloud account grows one resource at a time \u2014 a bucket here for a one-off export, an instance\nthere for a proof of concept \u2014 and nobody remembers every rule that was supposed to apply. Then a\ncustomer asks for a compliance report, or a security review flags an S3 bucket that turned out to\nbe public, and someone has to answer: which of our resources actually follow policy, right now,\nwith evidence? Checking that by hand, resource by resource, does not scale past a handful of\nbuckets. This module builds the tool that answers it on demand, with a paper trail an auditor can\ncheck independently."})}),"\n",(0,o.jsx)(n.h2,{id:"1-the-inspectors-checklist-not-the-repair-crew",children:"1. The inspector's checklist, not the repair crew"}),"\n",(0,o.jsx)(n.p,{children:'Picture a building inspector who visits a construction site with a written checklist: smoke\ndetectors installed, fire exits clear, wiring up to code. The inspector\'s job stops at the\nchecklist. They walk the site, mark every item pass or fail, write down exactly what they saw \u2014\n"exit on the third floor blocked by stored furniture," not just "fail" \u2014 and hand the building\nowner a citation report. The inspector does not move the furniture. A separate maintenance crew\ndoes that, on their own schedule, using the citation report as their work order.'}),"\n",(0,o.jsx)(n.p,{children:"Keeping those two roles apart is not bureaucracy for its own sake. An inspector who also fixes\nproblems on the spot has a reason to look the other way on a minor issue to save time, and a\nbuilding owner has no independent record of what was actually found before it got fixed. A written\nreport, produced by someone whose only job is to look and record, is worth more precisely because\nthe inspector cannot also make the problem disappear."}),"\n",(0,o.jsxs)(n.p,{children:["This module's ",(0,o.jsx)(n.code,{children:"cloudaudit.py"})," is the inspector. It checks real AWS resources against a written\npolicy \u2014 required tags, approved regions, age, encryption, public exposure \u2014 and produces a\nfindings report with exact evidence for every violation. It never deletes a bucket, never changes a\ntag, never locks down a public ACL. A later module, ",(0,o.jsx)(n.strong,{children:"Safe Cloud Remediation"}),", is the maintenance\ncrew \u2014 a separate tool, reading this module's findings as its work order, run deliberately and on\nits own schedule. This module ships no code that calls a write-mode AWS API (",(0,o.jsx)(n.code,{children:"put_*"}),", ",(0,o.jsx)(n.code,{children:"delete_*"}),",\n",(0,o.jsx)(n.code,{children:"create_*"}),", ",(0,o.jsx)(n.code,{children:"modify_*"}),") against a resource it is auditing \u2014 the Deep Dive proves that mechanically,\nnot just by description."]}),"\n",(0,o.jsx)(n.mermaid,{value:'flowchart LR\n    P["policy.yaml\\n(written rules)"] --\x3e D\n    R["Real AWS resources\\n(via boto3, read-only calls)"] --\x3e E["Evidence gathering\\n(gather_bucket_evidence)"]\n    E --\x3e D["Detection\\n(evaluate_policy)\\npure, no network calls"]\n    D --\x3e F["Findings\\n(severity + evidence + suppression)"]\n    F --\x3e AR["Audit report\\n(the citation report)"]\n    AR -.->|"read by a separate tool,\\nModule 25 -- not this one"| M["Remediation\\n(fix the violation)"]\n    style M stroke:#888,stroke-dasharray: 4 4'}),"\n",(0,o.jsx)(n.p,{children:"The dashed box is deliberate: this module's diagram stops at the audit report. Remediation is\nsomeone else's job, in a later module."}),"\n",(0,o.jsx)(n.h2,{id:"2-policy-as-data--rules-you-can-read-without-reading-python",children:"2. Policy as data \u2014 rules you can read without reading Python"}),"\n",(0,o.jsxs)(n.p,{children:[(0,o.jsx)(n.code,{children:"cloudaudit.py"}),"'s rules do not live in ",(0,o.jsx)(n.code,{children:"if"})," statements scattered through the code. They live in a\nYAML file, ",(0,o.jsx)(n.code,{children:"policy.yaml"}),", that a compliance lead who has never opened Python can read and reason\nabout:"]}),"\n",(0,o.jsx)(n.pre,{children:(0,o.jsx)(n.code,{className:"language-yaml",children:'rules:\n  - id: required-tags\n    check: required_tags\n    severity: high\n    required_tags: [team_owner, environment]\n\n  - id: no-public-exposure\n    check: no_public_exposure\n    severity: critical\n    applies_to: [s3-bucket]\n\nexceptions:\n  - resource_id: platformops-legacy-reports\n    rule_id: required-tags\n    reason: "legacy bucket predates the tagging policy -- cleanup tracked in OPS-4021"\n    expires: "2026-12-31"\n'})}),"\n",(0,o.jsxs)(n.p,{children:["Each rule has an ",(0,o.jsx)(n.code,{children:"id"})," (matched against exceptions), a ",(0,o.jsx)(n.code,{children:"check"})," (which built-in check function runs \u2014\n",(0,o.jsx)(n.code,{children:"required_tags"}),", ",(0,o.jsx)(n.code,{children:"approved_regions"}),", ",(0,o.jsx)(n.code,{children:"max_age_days"}),", ",(0,o.jsx)(n.code,{children:"require_encryption"}),", ",(0,o.jsx)(n.code,{children:"no_public_exposure"}),"),\nand a ",(0,o.jsx)(n.code,{children:"severity"}),". ",(0,o.jsx)(n.code,{children:"applies_to"})," is optional: leaving it out means the rule applies to every resource\ntype this module gathers evidence for; naming resource types (",(0,o.jsx)(n.code,{children:"[s3-bucket]"}),') keeps a rule like\n"require encryption" from being silently meaningless against a resource type this module has no\nencryption evidence for at all.']}),"\n",(0,o.jsx)(n.p,{children:'Changing what counts as a violation \u2014 adding a region to the approved list, raising the maximum\nage from 90 days to 180 \u2014 means editing this file, not shipping a code change. That is the entire\npoint of "policy as data": the rule and the code that enforces it are two different things, and only\none of them needs a pull request to change.'}),"\n",(0,o.jsx)(n.h2,{id:"3-evidence-composes-with-the-inventory-it-does-not-duplicate-it",children:"3. Evidence composes with the inventory, it does not duplicate it"}),"\n",(0,o.jsxs)(n.p,{children:["Module 23's ",(0,o.jsx)(n.code,{children:"multiregion.py"})," already discovers S3 buckets \u2014 ",(0,o.jsx)(n.code,{children:"list_s3_buckets()"})," returns each\nbucket's ",(0,o.jsx)(n.code,{children:"resource_id"}),", ",(0,o.jsx)(n.code,{children:"region"})," and ",(0,o.jsx)(n.code,{children:"tags"})," as a ",(0,o.jsx)(n.code,{children:"ResourceRecord"}),". This module's policy checks need\nmore than that: whether a bucket is encrypted with a customer-managed key, whether its ACL exposes\nit publicly, how old it is. Two ways to get there were on the table: add those fields directly onto\n",(0,o.jsx)(n.code,{children:"ResourceRecord"}),", or build something new that wraps a ",(0,o.jsx)(n.code,{children:"ResourceRecord"})," and adds only what this\nmodule needs."]}),"\n",(0,o.jsxs)(n.p,{children:["Adding audit-only fields onto ",(0,o.jsx)(n.code,{children:"ResourceRecord"}),' would mean every other caller of that dataclass \u2014 a\nplain inventory report, a CSV export, any future module that just wants "what exists, with what\ntags" \u2014 carries fields it never fills in, always ',(0,o.jsx)(n.code,{children:"None"}),". This module instead defines\n",(0,o.jsx)(n.code,{children:"ResourceEvidence"}),", which wraps one ",(0,o.jsx)(n.code,{children:"ResourceRecord"})," and adds exactly ",(0,o.jsx)(n.code,{children:"encrypted"}),", ",(0,o.jsx)(n.code,{children:"public"})," and\n",(0,o.jsx)(n.code,{children:"created_at"}),". ",(0,o.jsx)(n.code,{children:"multiregion.list_s3_buckets()"})," still does the one thing it always did; this module's\nown ",(0,o.jsx)(n.code,{children:"gather_bucket_evidence()"})," is the only place that adds the extra evidence, and it is the only\nplace in this module that makes AWS calls at all."]}),"\n",(0,o.jsx)(n.mermaid,{value:'flowchart LR\n    LB["multiregion.list_s3_buckets()\\n(Module 23 -- unchanged)"] --\x3e RR["ResourceRecord\\n(resource_id, region, tags)"]\n    RR --\x3e GE["gather_bucket_evidence()\\n(this module, the only network calls)"]\n    GE --\x3e RE["ResourceEvidence\\n(+ encrypted, public, created_at)"]\n    RE --\x3e EP["evaluate_policy()\\n(pure, zero network calls)"]'}),"\n",(0,o.jsx)(n.h2,{id:"4-detection-is-pure--provably-not-just-by-convention",children:"4. Detection is pure \u2014 provably, not just by convention"}),"\n",(0,o.jsxs)(n.p,{children:[(0,o.jsx)(n.code,{children:"evaluate_policy()"})," takes a list of already-gathered ",(0,o.jsx)(n.code,{children:"ResourceEvidence"})," and a loaded policy, and\nreturns a list of ",(0,o.jsx)(n.code,{children:"Finding"})," objects. It never builds a boto3 client, never mentions ",(0,o.jsx)(n.code,{children:"client"}),"\nanywhere in its body, and never touches the network. That is what makes it fully unit-testable\nwithout Floci running at all: every detection test in this module's test suite hand-builds evidence\ndirectly and asserts on the findings that come back, no live AWS emulator required."]}),"\n",(0,o.jsxs)(n.p,{children:["Splitting evidence-gathering (",(0,o.jsx)(n.code,{children:"gather_bucket_evidence()"}),", the only network-touching function here)\nfrom detection (",(0,o.jsx)(n.code,{children:"evaluate_policy()"}),', pure) is the same "separate detection from remediation" idea\nfrom section 1, one layer deeper: even inside the inspector\'s own work, "go look at the site" and\n"decide whether what I saw violates the checklist" are kept apart. A bug in the detection logic\nshould never require a live AWS connection to catch in a test; a bug in evidence-gathering should\nnever be confused with a bug in what counts as a violation.']}),"\n",(0,o.jsx)(n.h2,{id:"5-a-finding-carries-evidence-not-a-bare-verdict",children:"5. A finding carries evidence, not a bare verdict"}),"\n",(0,o.jsxs)(n.p,{children:["A ",(0,o.jsx)(n.code,{children:"Finding"}),' is not just "resource X failed rule Y." It carries the exact evidence that proved the\nviolation, as a specific string:']}),"\n",(0,o.jsx)(n.pre,{children:(0,o.jsx)(n.code,{className:"language-json",children:'{\n  "resource_id": "platformops-audit-no-kms",\n  "resource_type": "s3-bucket",\n  "rule_id": "require-encryption",\n  "severity": "high",\n  "evidence": "encryption: not using a customer-managed KMS key (AWS-managed SSE-S3 default only)",\n  "suppressed": false,\n  "suppression_reason": null\n}\n'})}),"\n",(0,o.jsxs)(n.p,{children:['That distinction matters more than it looks. Real AWS \u2014 and Floci, which matches this behavior \u2014\nturns on default SSE-S3 encryption for every bucket automatically, the moment it is created, and\nhas done so since January 2023. A check that only asks "does this bucket have any default\nencryption configured" would find zero violations on any real account today, because the answer is\nalways yes. The actual compliance question worth auditing is narrower \u2014 does this bucket use a\n',(0,o.jsx)(n.strong,{children:"customer-managed KMS key"}),", which many compliance frameworks specifically require for key\nrotation control and CloudTrail audit visibility, versus the AWS-managed default that gives you\nneither. ",(0,o.jsx)(n.code,{children:"evidence"}),' says exactly that ("not using a customer-managed KMS key"), not a bare ',(0,o.jsx)(n.code,{children:"false"}),'\nthat would leave an auditor guessing which kind of "not encrypted" they were looking at. The Deep\nDive shows this finding next to the real API response that produced it.']}),"\n",(0,o.jsx)(n.h2,{id:"6-exceptions-suppress-they-never-delete",children:"6. Exceptions suppress, they never delete"}),"\n",(0,o.jsxs)(n.p,{children:["A policy will always have legitimate exceptions \u2014 a legacy bucket scheduled for cleanup next\nquarter, a resource whose owner has an approved waiver. ",(0,o.jsx)(n.code,{children:"policy.yaml"}),"'s ",(0,o.jsx)(n.code,{children:"exceptions"})," list matches\none ",(0,o.jsx)(n.code,{children:"(resource_id, rule_id)"})," pair to a reason and an expiry date. When ",(0,o.jsx)(n.code,{children:"evaluate_policy()"})," finds a\nviolation that also matches an unexpired exception, it still creates the ",(0,o.jsx)(n.code,{children:"Finding"})," \u2014 it just marks\n",(0,o.jsx)(n.code,{children:"suppressed: true"})," and fills in ",(0,o.jsx)(n.code,{children:"suppression_reason"}),". The finding stays in the report, visible, not\nquietly dropped from a shorter list."]}),"\n",(0,o.jsx)(n.p,{children:'That distinction is the whole point of tracking exceptions at all. A report that silently excludes\nexcepted resources looks identical to a report where those resources were never checked \u2014 an\nauditor reviewing it cannot tell "we know about this and decided to accept the risk until a\ndeadline" from "nobody looked." A report that shows the suppressed finding, with its reason and\nexpiry, makes that decision visible and reviewable.'}),"\n",(0,o.jsxs)(n.p,{children:["An exception's ",(0,o.jsx)(n.code,{children:"expires"})," date is not decorative. ",(0,o.jsx)(n.code,{children:"evaluate_policy()"})," checks it against ",(0,o.jsx)(n.code,{children:"now"})," on\nevery run: an exception with a past ",(0,o.jsx)(n.code,{children:"expires"})," date no longer suppresses anything, and the finding\nit used to excuse goes back to being active. Nothing has to happen for that switch to flip \u2014 the\nsame exception, re-evaluated the day after it expires, produces a different result, because the\npolicy was written to expect that."]}),"\n",(0,o.jsx)(n.h2,{id:"common-pitfalls",children:"Common pitfalls"}),"\n",(0,o.jsxs)(n.ul,{children:["\n",(0,o.jsxs)(n.li,{children:[(0,o.jsx)(n.strong,{children:"Conflating detection with remediation."}),' The moment an "audit" script starts calling\n',(0,o.jsx)(n.code,{children:"delete_bucket()"})," or ",(0,o.jsx)(n.code,{children:"put_bucket_tagging()"})," to fix what it finds, it stops being an audit \u2014 there\nis no longer an independent report of what was found before it changed. Keep the two as separate\ntools, even when it would be faster to combine them."]}),"\n",(0,o.jsxs)(n.li,{children:[(0,o.jsx)(n.strong,{children:"Silently dropping suppressed findings instead of showing them."})," A shorter report that hides\nexcepted resources looks the same as a report that never checked them at all. Show every\nsuppressed finding, with its reason, right alongside the active ones."]}),"\n",(0,o.jsxs)(n.li,{children:[(0,o.jsx)(n.strong,{children:"A policy rule with no severity."})," Every rule needs one \u2014 a report where every finding looks\nequally urgent is not more urgent, it is less useful; nobody can tell what to act on first."]}),"\n",(0,o.jsxs)(n.li,{children:[(0,o.jsx)(n.strong,{children:"Treating an expired exception as still valid."})," An exception's ",(0,o.jsx)(n.code,{children:"expires"})," date has to be checked\nagainst the current date on every run, not just recorded once when the exception was written. A\nsuppression that never re-checks its own expiry quietly becomes permanent."]}),"\n",(0,o.jsxs)(n.li,{children:[(0,o.jsx)(n.strong,{children:'Assuming "not encrypted" means the bucket has no encryption at all.'})," On a real account today,\nit almost always does \u2014 the AWS-managed SSE-S3 default. The evidence has to say which kind of\nencryption is missing (a customer-managed key, specifically), or the finding is misleading."]}),"\n"]})]})}function u(e={}){let{wrapper:n}={...(0,s.R)(),...e.components};return n?(0,o.jsx)(n,{...e,children:(0,o.jsx)(h,{...e})}):h(e)}},7684(e,n,t){t.d(n,{A:()=>s});var i=t(4848);t(6540);var o=t(6497);function s({src:e,title:n="Slides"}){let t=(0,o.Ay)(e);return(0,i.jsxs)("div",{className:"deck_nWXz",children:[(0,i.jsxs)("div",{className:"bar_dOoE",children:[(0,i.jsxs)("span",{className:"label_ZSLR",children:["\u25B6 ",n]}),(0,i.jsx)("a",{className:"full_PrDQ",href:t,target:"_blank",rel:"noopener noreferrer",children:"Open fullscreen \u2197"})]}),(0,i.jsx)("div",{className:"frame_M4DO",children:(0,i.jsx)("iframe",{src:t,title:n,loading:"lazy",allowFullScreen:!0})})]})}},8453(e,n,t){t.d(n,{R:()=>a,x:()=>r});var i=t(6540);let o={},s=i.createContext(o);function a(e){let n=i.useContext(s);return i.useMemo(function(){return"function"==typeof e?e(n):{...n,...e}},[n,e])}function r(e){let n;return n=e.disableParentContext?"function"==typeof e.components?e.components(o):e.components||o:a(e.components),i.createElement(s.Provider,{value:n},e.children)}}}]);